import{z as o,x as s,o as A,c as d,q as t,j as l,D as a,d as B,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"并购浪潮","description":"","frontmatter":{"title":"并购浪潮","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-merger-waves.md","filePath":"econ/cf-merger-waves.md","lastUpdated":1791413859000}'),C={name:"econ/cf-merger-waves.md"};function h(p,E,c,f,D,m){const r=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="并购浪潮" tabindex="-1">并购浪潮 <a class="header-anchor" href="#并购浪潮" aria-label="Permalink to &quot;并购浪潮&quot;">​</a></h1><div class="epigraph"><p>并购浪潮不是贪婪的周期，而是行业冲击、估值差与资本流动性三样东西同时在场的窗口；少一样，同样的协同效应就只剩纸面。</p><footer>—— 据 Mitchell–Mulherin 1996 与 Harford 2005 整理</footer></div><p><a href="/econ/cf-ipo-timing">上一课</a>把发行时机钉在估值窗口上：企业在自己的股份贵时卖。并购把同一逻辑推到极端——不是发新股买项目，而是用股票或现金买现成的资产包；收购方的「发行窗口」，就是目标的估值低谷。单笔合并的价格效应由<a href="/econ/merger-simulation">合并模拟</a>处理（内部化交叉弹性、UPP 筛查），本课钉时间维度：并购为什么在历史上一波一波到来，价值又在浪潮里流向谁。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>并购活动呈波状：1890 年代横向合并、1920 年代纵向整合、1960 年代混合集团、1980 年代杠杆与分拆、1990 年代战略并购与股票支付、此后私募资本与产业整合交替。要解释的不是「为什么并购」，而是<strong>同时性</strong>：协同机会为什么不来则已、来则成潮。Mitchell–Mulherin 1996 给出行业层面的起点：并购与重组活动对经济、监管和技术冲击的反应成簇，冲击在同一时间改变一个行业里所有企业的可行集。Harford 2005 补条件：行业冲击要叠上充足的资本流动性，才形成可观测的浪潮。Shleifer–Vishny 2003 再补一层动因：估值差本身可以是动机——被高估的公司用股票买相对便宜的资产，把高估值「变现」成规模。</p><p><span class="marginnote">直觉类比：行业冲击像同时响铃的开赛哨——管制的口子一开、新技术一落地，全行业的潜在配对机会同一分钟涌出，而不是零星出现。解释并购浪潮，就是解释「为什么哨声一响大家都同时跑」，而不是解释某一个人为什么跑步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把浪潮当行业层面的均衡现象来测，而不是逐笔交易的故事：在行业层对齐三条时间序列——冲击日程、融资条件的量、支付方式构成——再看浪潮起点落在哪个组合上。支付方式是框架里最锋利的读数：它把不可观测的估值差翻译成可观测的会计选择。三要素的拆法与拼法如下。</p><h3 id="三要素框架" tabindex="-1">三要素框架 <a class="header-anchor" href="#三要素框架" aria-label="Permalink to &quot;三要素框架&quot;">​</a></h3><p>把浪潮拆成三要素再拼回去：同时性冲击（放松管制、技术变迁）扩大可行集；估值差（收购方与目标的相对估值）决定支付方式——差大用股票，差小用现金；资本流动性（信贷与私募资本的可得性）决定可行集能否被执行。检验在行业层面对齐三条时间序列：冲击时点、浪潮起点、支付方式构成。</p><p><span class="marginnote">把支付方式翻译成大白话：用股票买＝「我拿自家股份当钞票」，只有我贵、它便宜时才划算，等于把估值差写进会计科目；用现金买＝「我按现价成交」，不表态谁贵谁贱。后来者看浪潮先看支付构成，就像先用温度计量估值差的体温。</span></p>',11)),(A(),l(n,null,{default:a(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E8%A1%8C%E4%B8%9A%E5%86%B2%E5%87%BB%EF%BC%9A%E7%AE%A1%E5%88%B6%E4%B8%8E%E6%8A%80%E6%9C%AF%22%5D%20--%3E%20FEAS%5B%22%E5%85%A8%E8%A1%8C%E4%B8%9A%E5%8F%AF%E8%A1%8C%E9%9B%86%E6%89%A9%E5%A4%A7%22%5D%0A%20%20FEAS%20--%3E%20GAP%5B%22%E4%BC%B0%E5%80%BC%E5%B7%AE%EF%BC%9A%E4%B9%B0%E6%96%B9%E8%B4%B5%E7%9B%AE%E6%A0%87%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20LIQ%5B%22%E8%B5%84%E6%9C%AC%E6%B5%81%E5%8A%A8%E6%80%A7%E5%85%85%E8%B6%B3%22%5D%20--%3E%20EXEC%5B%22%E4%BA%A4%E6%98%93%E8%A2%AB%E6%89%A7%E8%A1%8C%22%5D%0A%20%20GAP%20--%3E%20PAY%7B%22%E4%BC%B0%E5%80%BC%E5%B7%AE%E5%A4%A7%3F%22%7D%0A%20%20PAY%20--%3E%7C%E6%98%AF%7C%20STOCK%5B%22%E8%82%A1%E7%A5%A8%E6%94%AF%E4%BB%98%E4%B8%BA%E4%B8%BB%22%5D%0A%20%20PAY%20--%3E%7C%E5%90%A6%7C%20CASH%5B%22%E7%8E%B0%E9%87%91%E6%94%AF%E4%BB%98%E4%B8%BA%E4%B8%BB%22%5D%0A%20%20EXEC%20--%3E%20WAVE%5B%22%E5%B9%B6%E8%B4%AD%E6%B5%AA%E6%BD%AE%22%5D%20--%3E%20VALUE%5B%22%E4%BB%B7%E5%80%BC%E6%B5%81%E5%90%91%E7%9B%AE%E6%A0%87%E8%82%A1%E4%B8%9C%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[B("价值的分配不对称：目标股东获得正的公告异常收益，量级在两成上下；收购方平均近零甚至略负，股票支付时更差。这与估值差逻辑一致——用股票支付等于向市场承认自己贵。浪潮末端有共同特征：估值差收窄、协同声明的兑现率下降、反垄断审查收紧（"),e("a",{href:"/econ/merger-simulation"},"合并模拟"),B("的价格效应推到台前）。为什么事后看多数合并没给收购方创造价值，浪潮仍会发生：冲击同时激活了所有人的可行集与信念，个体的乐观、管理层帝国动机与「先例效应」在窗口内互相强化——每个参与者都在自己样本里理性，合起来是潮。")],-1)),(A(),l(n,null,{default:a(()=>[i(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%EF%BC%9A%E4%B8%80%E6%AC%A1%E8%B4%A2%E5%AF%8C%E5%86%8D%E5%88%86%E9%85%8D%22%5D%20--%3E%20T%5B%22%E7%9B%AE%E6%A0%87%E8%82%A1%E4%B8%9C%EF%BC%9A%E5%BC%82%E5%B8%B8%E6%94%B6%E7%9B%8A%E7%BA%A6%E4%B8%A4%E6%88%90%22%5D%0A%20%20D%20--%3E%20A%5B%22%E6%94%B6%E8%B4%AD%E6%96%B9%E8%82%A1%E4%B8%9C%EF%BC%9A%E8%BF%91%E9%9B%B6%E7%94%9A%E8%87%B3%E7%95%A5%E8%B4%9F%22%5D%0A%20%20ST%5B%22%E8%82%A1%E7%A5%A8%E6%94%AF%E4%BB%98%22%5D%20--%3E%20A2%5B%22%E6%9B%B4%E5%B7%AE%EF%BC%9A%E7%AD%89%E4%BA%8E%E6%89%BF%E8%AE%A4%E8%87%AA%E5%B7%B1%E8%82%A1%E4%BB%BD%E8%B4%B5%22%5D%0A%20%20Q%5B%22%E6%B5%AA%E6%BD%AE%E4%B8%BA%E4%BD%95%E4%BB%8D%E4%BC%9A%E5%8F%91%E7%94%9F%3F%22%5D%20--%3E%20B%5B%22%E5%86%B2%E5%87%BB%E5%90%8C%E6%97%B6%E7%82%B9%E7%87%83%E5%85%A8%E8%A1%8C%E4%B8%9A%E7%9A%84%E4%B9%90%E8%A7%82%E4%B8%8E%E4%BF%A1%E5%BF%B5%22%5D%0A%20%20B%20--%3E%20C%5B%22%E4%B8%AA%E4%BD%93%E5%90%84%E8%87%AA%E7%90%86%E6%80%A7%EF%BC%8C%E5%90%88%E8%B5%B7%E6%9D%A5%E6%88%90%E6%BD%AE%22%5D%0A%20%20C%20--%3E%20E%5B%22%E6%BD%AE%E6%9C%AB%EF%BC%9A%E4%BC%B0%E5%80%BC%E5%B7%AE%E6%94%B6%E7%AA%84%EF%BC%8C%E5%85%91%E7%8E%B0%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">Andrade–Mitchell–Stafford 2001 的样本显示：目标公司公告日异常收益两成以上，收购方在零附近；1980 年代以现金支付为主，1990 年代股票支付占比大幅上升——支付方式是当时估值差的直接读数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>浪潮只能事后认定，事前用估值与流动性指标识别，误报率高——「这一波不一样」是每次浪潮里最贵的一句话。协同效应的声明与实现落差大，声明不能当预期收益读。股票支付把并购与上一课的发行择时接在一起：用高估股份收购是把择时收益资本化，代价是事后弱势的股份沉淀在合并体内。杠杆侧的极端形态（收购与私募）另见<a href="/econ/lbo-private-equity">杠杆收购与私募股权</a>，本课不重复。</p><p><span class="marginnote">常见误区：把「协同效应声明」当预期收益读。声明是谈判文案，不是兑现承诺——事后研究里兑现率显著低于声明额，管理层动机与先例效应都会让声明偏乐观。读并购公告的正确姿势：先把它当成一个待检验的假设，再当成一个数字。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>浪潮是三要素的交集：行业冲击扩大可行集，估值差定支付方式，资本流动性定可行性。</li><li>价值分配不对称：目标股东拿走公告收益，收购方近零，股票支付时更差。</li><li>Shleifer–Vishny 2003：估值差本身就是动因，高估值公司用股票「变现」规模。</li><li>浪潮只能事后认定，协同声明不能当预期收益读。</li><li>出处：Mitchell–Mulherin 1996；Andrade–Mitchell–Stafford 2001；Shleifer–Vishny 2003；Harford 2005。</li></ul>',6))])}const _=o(C,[["render",h]]);export{F as __pageData,_ as default};
